import{_ as e,c as o,o as t,am as r}from"./chunks/framework.83COwwOK.js";const p=JSON.parse('{"title":"Vilinko Studio Privacy Policy","description":"","frontmatter":{},"headers":[],"relativePath":"en/agreement/privacy.md","filePath":"en/agreement/privacy.md"}'),a={name:"en/agreement/privacy.md"};function n(s,i,l,c,u,d){return t(),o("div",null,i[0]||(i[0]=[r('<h1 id="vilinko-studio-privacy-policy" tabindex="-1">Vilinko Studio Privacy Policy <a class="header-anchor" href="#vilinko-studio-privacy-policy" aria-label="Permalink to &quot;Vilinko Studio Privacy Policy&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">Version</p><p>Initial Release Date: August 6, 2025<br> Last Updated: June 8, 2026</p></div><h2 id="_1-introduction" tabindex="-1">1. Introduction <a class="header-anchor" href="#_1-introduction" aria-label="Permalink to &quot;1. Introduction&quot;">​</a></h2><p>Welcome to the internet information technology tools and related services provided by Vilinko Studio (hereinafter referred to as &quot;we,&quot; &quot;us,&quot; or &quot;our&quot;). This Privacy Policy is designed to explain how we collect, use, store, protect, and disclose your personal information, as well as the rights you hold regarding your personal data. This Privacy Policy is closely related to your use of our services. Please read and fully understand this policy carefully before using any of our services, <strong>particularly the terms highlighted in bold or underlined</strong>. By using or continuing to use our services, you express your consent to our processing of your personal information in accordance with this Privacy Policy. If you have any questions regarding this policy, please contact us through the methods provided herein.</p><h2 id="_2-scope-of-application" tabindex="-1">2. Scope of Application <a class="header-anchor" href="#_2-scope-of-application" aria-label="Permalink to &quot;2. Scope of Application&quot;">​</a></h2><ol><li>This Privacy Policy applies to all services provided by us, including but not limited to the user login system, forum services, personalized customization features, desktop beautification tools, file interpreters, and associated websites, clients, mini-programs, etc.</li><li>This Privacy Policy does not apply to: <ul><li>Products or services provided to you by third parties through our services. Such third-party services may have independent privacy policies, and we are not responsible for the privacy policies or practices of any third party.</li><li>Third-party services authorized by us, provided that such authorization does not constitute consent for the third party to collect or use your personal information. Third parties shall process your information in accordance with their own privacy policies.</li></ul></li></ol><h2 id="_3-information-we-collect" tabindex="-1">3. Information We Collect <a class="header-anchor" href="#_3-information-we-collect" aria-label="Permalink to &quot;3. Information We Collect&quot;">​</a></h2><h3 id="_1-information-you-voluntarily-provide" tabindex="-1">(1) Information You Voluntarily Provide <a class="header-anchor" href="#_1-information-you-voluntarily-provide" aria-label="Permalink to &quot;(1) Information You Voluntarily Provide&quot;">​</a></h3><ol><li><strong>Registration Information:</strong> When you register for a Vilinko Studio account, you may need to provide your mobile phone number, email address, username, password, and other relevant information. If you choose to log in via a third-party account (e.g., WeChat, QQ, GitHub, etc.), we will obtain your publicly available information on that third-party platform (such as nickname, avatar, etc.), subject to the content displayed on the third-party authorization page.</li><li><strong>Information Submitted During Service Utilization:</strong><ul><li>Posts, comments, replies, private messages, and other content you publish while using the forum services.</li><li>Uploaded images, preference parameters, textual descriptions, and other data you input while using personalized customization functions.</li><li>Opinions, suggestions, complaints, and relevant evidentiary materials submitted to us via our customer service system or feedback channels.</li></ul></li><li><strong>Other Voluntarily Provided Information:</strong> Such as your name, address, contact details, and other information provided when participating in our questionnaires, surveys, or promotional events.</li></ol><h3 id="_2-information-we-collect-automatically-during-your-use-of-services" tabindex="-1">(2) Information We Collect Automatically During Your Use of Services <a class="header-anchor" href="#_2-information-we-collect-automatically-during-your-use-of-services" aria-label="Permalink to &quot;(2) Information We Collect Automatically During Your Use of Services&quot;">​</a></h3><p>For specific permissions and information utilized by our applications, please refer to our <a href="./privacy_collect.html">Public Disclosure of Personal Information Collection</a>.</p><ol><li><strong>Device Information:</strong> Operating system type of the device.</li><li><strong>Network Information:</strong> Including IP address, network operator/ISP information, etc.</li><li><strong>Location Information:</strong><ul><li>If you consent to use features involving location services (such as location-based resource recommendations) and authorize us to access your location data, we may obtain your precise location information via GPS.</li><li>If you do not grant authorization, but the functionality of the service requires approximate location data to operate normally, we may determine your approximate geographic location based on your IP address or other alternative data.</li><li>You may revoke your location permission at any time through your device&#39;s system settings or the permission management within our services. Once revoked, we will cease collecting this data, though it may affect the functionality of certain services.</li></ul></li><li><strong>Log Information:</strong><ul><li><strong>Access Logs:</strong> Including the time of your access, pages or features visited, click records, etc.</li><li><strong>Operation Logs:</strong> Including your operational behaviors within the service (such as login, logout, settings modifications, file uploads, resource downloads, etc.), operational results, and error logs.</li><li><strong>Device Runtime Logs:</strong> Including the operational status of the service on your device, crash information, and exception logs.</li></ul></li><li><strong>File Information:</strong><ul><li>When you use file upload features, we temporarily read the contents of the file selected for interpretation strictly to execute the requested operation. Upon completion, temporary data will be permanently cleared (unless you explicitly choose to save the results).</li><li>Files you upload or store through our services (such as personalized beautification assets, forum attachments, etc.) will be stored and managed in accordance with your explicit settings.</li></ul></li></ol><h3 id="_3-information-obtained-from-third-parties" tabindex="-1">(3) Information Obtained from Third Parties <a class="header-anchor" href="#_3-information-obtained-from-third-parties" aria-label="Permalink to &quot;(3) Information Obtained from Third Parties&quot;">​</a></h3><ol><li>If you use our services through a third-party partner platform or authorize a third party to provide your information to us, we will obtain your relevant information from such third parties to the extent permitted by applicable laws and regulations, subject to your agreements and authorization scope with the third party.</li><li>To ensure service security and mitigate fraud risks, we may obtain risk assessment information regarding your account from legally compliant third-party institutions.</li></ol><h2 id="_4-how-we-use-the-information" tabindex="-1">4. How We Use the Information <a class="header-anchor" href="#_4-how-we-use-the-information" aria-label="Permalink to &quot;4. How We Use the Information&quot;">​</a></h2><ol><li><strong>Service Provision:</strong> To create an account for you based on your registration information, ensure the proper functioning of various service features, and process corresponding commands based on your operations (such as file interpretation and forum posting).</li><li><strong>Service Experience Optimization:</strong> To optimize the compatibility and stability of our services across different devices and to repair vulnerabilities and system glitches based on device information and runtime logs.</li><li><strong>Service Security &amp; Safeguards:</strong><ul><li>Utilizing device, network, and log information to identify abnormal logins, malicious attacks, and other security risks, thereby implementing technical measures to safeguard your account and data.</li><li>Monitoring and handling behaviors that violate applicable laws, regulations, or our service agreements to maintain public order within the platform.</li><li>Identifying and preventing malicious access activities initiated by automated bots.</li></ul></li><li><strong>Communication and Notifications:</strong><ul><li>Sending service-related notices (such as successful registration notifications, password reset reminders, service update announcements, etc.).</li><li>Pushing promotional event information with your prior consent. You can opt out or disable these communications at any time via the corresponding settings.</li></ul></li><li><strong>Legal Compliance and Rights Protection:</strong><ul><li>Utilizing your information to comply with legal obligations, statutory duties, or to respond to legitimate requests from judicial or administrative authorities.</li><li>Utilizing your information within a reasonably necessary scope to protect the legitimate rights and interests of both us and our users (such as responding to litigation or arbitration).</li></ul></li><li><strong>Other Uses with Your Explicit Consent:</strong> For purposes such as market research or product improvement, we will explicitly inform you and obtain your consent prior to processing.</li></ol><h2 id="_5-storage-and-protection-of-information" tabindex="-1">5. Storage and Protection of Information <a class="header-anchor" href="#_5-storage-and-protection-of-information" aria-label="Permalink to &quot;5. Storage and Protection of Information&quot;">​</a></h2><h3 id="_1-location-of-storage" tabindex="-1">(1) Location of Storage <a class="header-anchor" href="#_1-location-of-storage" aria-label="Permalink to &quot;(1) Location of Storage&quot;">​</a></h3><ul><li>Your personal information will be stored on servers located within the territory of the People&#39;s Republic of China.</li></ul><h3 id="_2-retention-period" tabindex="-1">(2) Retention Period <a class="header-anchor" href="#_2-retention-period" aria-label="Permalink to &quot;(2) Retention Period&quot;">​</a></h3><ul><li>We determine reasonable retention periods based on the type and purpose of the information: <ul><li><strong>Account Information:</strong> Retained continuously while your account remains active. If you terminate/delete your account, we will delete or anonymize your personal information within a reasonable timeframe.</li><li>Where applicable laws and regulations dictate otherwise, such statutory retention periods shall prevail (e.g., information retained for the fulfillment of statutory duties or dispute resolution may be kept for a longer duration).</li></ul></li></ul><h3 id="_3-protective-measures" tabindex="-1">(3) Protective Measures <a class="header-anchor" href="#_3-protective-measures" aria-label="Permalink to &quot;(3) Protective Measures&quot;">​</a></h3><ul><li>We implement technical safeguards, including encryption technologies (such as SSL/TLS encrypted transmission, data encryption at rest), access control mechanisms, firewalls, and intrusion detection systems, to protect information from unauthorized access, leakage, tampering, or damage.</li><li>We have established a data security incident emergency response plan. In the event of a security incident such as a data breach, we will promptly execute remedy actions, report to competent authorities, and notify you in accordance with regulatory requirements.</li></ul><h2 id="_6-sharing-transfer-and-public-disclosure-of-information" tabindex="-1">6. Sharing, Transfer, and Public Disclosure of Information <a class="header-anchor" href="#_6-sharing-transfer-and-public-disclosure-of-information" aria-label="Permalink to &quot;6. Sharing, Transfer, and Public Disclosure of Information&quot;">​</a></h2><h3 id="_1-sharing" tabindex="-1">(1) Sharing <a class="header-anchor" href="#_1-sharing" aria-label="Permalink to &quot;(1) Sharing&quot;">​</a></h3><ul><li>We will not share your personal information with any third party, except under the following circumstances: <ul><li><strong>With Your Explicit Consent:</strong> Prior to sharing, we will explicitly inform you of the purpose, the identity of the third party, and the scope of the information, and proceed only upon obtaining your explicit confirmation.</li><li><strong>Service Necessity:</strong> To provide you with services, we may share necessary information with third-party service providers (such as server hosting providers, cloud storage vendors, payment processors, etc.). Such third parties may only use the information within the scope of providing the service and are strictly contractually bound by confidentiality obligations.</li><li><strong>Legal Mandates:</strong> Sharing information in accordance with laws, regulations, or mandatory requests from judicial or administrative authorities.</li><li><strong>Protection of Legitimate Interests:</strong> Sharing information with relevant parties within a reasonably necessary scope to protect the legitimate rights and interests of us and our users (such as fraud prevention or addressing intellectual property infringements).</li></ul></li></ul><h3 id="_2-transfer" tabindex="-1">(2) Transfer <a class="header-anchor" href="#_2-transfer" aria-label="Permalink to &quot;(2) Transfer&quot;">​</a></h3><ul><li>We will not transfer your personal information to any third party without your explicit consent. In the event of corporate mergers, divisions, acquisitions, restructuring, or similar corporate transactions requiring the transfer of personal data, we will notify you in advance and ensure that the successor entity continues to abide by this Privacy Policy. If you object, you may choose to terminate your account.</li></ul><h3 id="_3-public-disclosure" tabindex="-1">(3) Public Disclosure <a class="header-anchor" href="#_3-public-disclosure" aria-label="Permalink to &quot;(3) Public Disclosure&quot;">​</a></h3><ul><li>We will not publicly disclose your personal information except under the following circumstances: <ul><li>Upon obtaining your explicit consent.</li><li>Pursuant to legal requirements or directives from competent authorities.</li><li>Within a necessary scope to protect public interest (such as combating criminal activities).</li><li>Information you voluntarily make public within the services (such as public forum posts), the scope of which shall be governed by your personal visibility settings.</li></ul></li></ul><h2 id="_7-your-rights" tabindex="-1">7. Your Rights <a class="header-anchor" href="#_7-your-rights" aria-label="Permalink to &quot;7. Your Rights&quot;">​</a></h2><ol><li><strong>Right of Access:</strong> You have the right to access your personal information (such as basic account info, usage records, etc.).</li><li><strong>Right to Rectification:</strong> If you discover that your information is inaccurate or incomplete, you have the right to request a rectification, which we will process promptly upon verification.</li><li><strong>Right to Erasure (Right to be Forgotten):</strong> You may request the deletion of your personal information under the following circumstances: <ul><li>The purpose for which the information was collected or processed has been achieved or is no longer necessary.</li><li>You withdraw your consent/authorization.</li><li>Our processing of your information violates applicable laws, regulations, or service agreements.</li><li>Other circumstances provided by law.</li><li>We will delete the data promptly upon verification. If retention is required by laws and regulations, we will subject such data to anonymization.</li></ul></li><li><strong>Right to Withdraw Consent:</strong> You may withdraw your authorization for us to collect and use your data at any time (e.g., by disabling device permissions). However, withdrawing consent may result in the unavailability of certain service features.</li><li><strong>Right to Data Portability:</strong> You have the right to request a copy of your personal information, which we will provide in a structured, commonly used format under reasonable and lawful conditions.</li><li><strong>Right to Account Termination:</strong> You can terminate your account via the account closure feature within the service or by contacting customer support. Upon termination, we will cease providing services to you and handle your data (via deletion or anonymization) in compliance with legal requirements.</li><li><strong>Right to Contesting Automated Decision-making:</strong> For decisions that significantly affect your rights and interests made solely through automated decision-making mechanisms (such as algorithmic recommendations), you have the right to demand an explanation, and you may refuse the processing of your information through purely automated means.</li></ol><h2 id="_8-protection-of-minors" tabindex="-1">8. Protection of Minors <a class="header-anchor" href="#_8-protection-of-minors" aria-label="Permalink to &quot;8. Protection of Minors&quot;">​</a></h2><ol><li>We attach the utmost importance to the protection of minors&#39; personal information. If you are a minor under the age of 18, you must use our services under the guidance and supervision of a parent or legal guardian, who should read this Privacy Policy on your behalf.</li><li>Parents or legal guardians of minors should properly manage the accounts and personal information of minors. If you discover that a minor&#39;s information has been improperly collected or used, please contact us immediately.</li><li>We do not provide age-inappropriate service content to minors, nor will we disclose a minor&#39;s personal information to third parties without the prior consent of their guardian.</li></ol><h2 id="_9-revisions-and-notifications-to-this-policy" tabindex="-1">9. Revisions and Notifications to This Policy <a class="header-anchor" href="#_9-revisions-and-notifications-to-this-policy" aria-label="Permalink to &quot;9. Revisions and Notifications to This Policy&quot;">​</a></h2><ol><li>We may revise this Privacy Policy from time to time due to amendments in applicable laws and regulations, adjustments to service features, or other operational changes.</li><li>The revised Privacy Policy will be published in prominent locations on our official website or service clients, with the effective date clearly indicated. If the revisions involve material changes to your rights or interests, we will prominently notify you via pop-up alerts, SMS, emails, or similar means, providing you with a reasonable consideration period.</li><li>Your continued use of our services constitutes your acceptance of the revised Privacy Policy. If you do not agree with the updated terms, you must immediately cease using our services.</li></ol><h2 id="_10-contact-us" tabindex="-1">10. Contact Us <a class="header-anchor" href="#_10-contact-us" aria-label="Permalink to &quot;10. Contact Us&quot;">​</a></h2><ul><li>If you have any questions, suggestions, or complaints regarding this Privacy Policy, you may reach out to us via the following communication channels: <ul><li>Email: <a href="mailto:privacy@vilinko.com" target="_blank" rel="noreferrer">privacy@vilinko.com</a></li><li><a href="https://support.vilinko.com" target="_blank" rel="noreferrer">Vilinko Support &amp; Feedback Center</a></li></ul></li></ul><h2 id="appendix-third-party-policy-links" tabindex="-1">Appendix: Third-Party Policy Links <a class="header-anchor" href="#appendix-third-party-policy-links" aria-label="Permalink to &quot;Appendix: Third-Party Policy Links&quot;">​</a></h2><ul><li><a href="https://afdian.com/term" target="_blank" rel="noreferrer">Afdian Platform Terms of Service</a></li></ul>',40)]))}const m=e(a,[["render",n]]);export{p as __pageData,m as default};
